{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "table"
  },
  "width": 300,
  "height": 300,
  "mark": {
    "type": "bar"
  },
  "encoding": {
    "x": {
      "field": "query",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "q_number"
      }
    },
    "y": {
      "field": "median_ms",
      "type": "quantitative",
      "title": "median ms"
    },
    "xOffset": {
      "field": "engine",
      "type": "nominal"
    },
    "color": {
      "field": "engine",
      "type": "nominal"
    },
    "column": {
      "field": "node",
      "type": "nominal",
      "title": null
    },
    "tooltip": [
      {
        "field": "node"
      },
      {
        "field": "query"
      },
      {
        "field": "engine"
      },
      {
        "field": "config_name"
      },
      {
        "field": "median_ms"
      },
      {
        "field": "n_runs"
      }
    ],
    "opacity": {
      "field": "config_name",
      "type": "nominal",
      "title": "config",
      "scale": {
        "range": [
          1.0,
          0.55,
          0.3
        ]
      }
    }
  },
  "config": {
    "background": null,
    "font": "ui-monospace, Menlo, Consolas, monospace",
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 12,
      "grid": true,
      "gridColor": "#8884",
      "domainColor": "#8886",
      "tickColor": "#8886"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 12
    },
    "view": {
      "stroke": "transparent"
    },
    "range": {
      "category": [
        "#0b5",
        "#c50",
        "#06c",
        "#a2b",
        "#888",
        "#c33"
      ]
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "table"
  },
  "facet": {
    "field": "query",
    "type": "nominal",
    "title": null,
    "sort": {
      "field": "q_number"
    }
  },
  "columns": 1,
  "spacing": 1,
  "spec": {
    "width": 420,
    "height": 180,
    "mark": {
      "type": "bar",
      "stroke": "#222",
      "strokeWidth": 0.006
    },
    "encoding": {
      "x": {
        "field": "node",
        "type": "nominal",
        "title": null,
        "axis": {
          "labelAngle": 0
        },
        "scale": {
          "paddingInner": 0.3,
          "paddingOuter": 0.15
        }
      },
      "y": {
        "field": "best_ms",
        "type": "quantitative",
        "title": "best ms"
      },
      "xOffset": {
        "field": "engine",
        "type": "nominal",
        "scale": {
          "paddingInner": 0.15
        }
      },
      "color": {
        "field": "engine",
        "type": "nominal",
        "scale": {
          "domain": ["b", "h", "v"],
          "range": ["#00BA38", "#F8766D", "#619CFF"]
        }
      },
      "tooltip": [
        {"field": "node"},
        {"field": "query"},
        {"field": "engine"},
        {"field": "best_ms"},
        {"field": "build_event_id", "type": "nominal", "title": "build"},
        {"field": "runs_considered"}
      ]
    }
  },
  "resolve": {
    "scale": {
      "y": "independent"
    },
    "axis": {
      "x": "independent"
    }
  },
  "config": {
    "background": null,
    "font": "ui-monospace, Menlo, Consolas, monospace",
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 12,
      "grid": true,
      "gridColor": "#8884",
      "domainColor": "#8886",
      "tickColor": "#8886"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 12
    },
    "view": {
      "stroke": "transparent"
    },
    "range": {
      "category": ["#0b6", "#c50", "#06c", "#a2b", "#888", "#c33"]
    }
  }
}

