{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "facet": {
    "row": {
      "field": "panel",
      "type": "nominal",
      "title": null,
      "header": {
        "labelAngle": 0,
        "labelAlign": "left",
        "labelFontWeight": "bold",
        "labelLimit": 320
      }
    }
  },
  "resolve": {
    "scale": {
      "color": "independent"
    },
    "legend": {
      "color": "independent"
    }
  },
  "spec": {
    "width": 468,
    "height": 96,
    "layer": [
      {
        "mark": {
          "type": "rect",
          "stroke": "#8883"
        },
        "encoding": {
          "color": {
            "field": "rel_to_best",
            "type": "quantitative",
            "title": "x best in panel",
            "scale": {
              "scheme": "viridis",
              "reverse": true
            },
            "legend": {
              "gradientLength": 80
            }
          }
        }
      },
      {
        "mark": {
          "type": "text",
          "fontSize": 9,
          "baseline": "middle"
        },
        "encoding": {
          "text": {
            "field": "median_ms",
            "type": "quantitative",
            "format": ".3s"
          },
          "color": {
            "condition": {
              "test": "datum.shade > 0.55",
              "value": "#fff"
            },
            "value": "#000"
          }
        }
      }
    ],
    "encoding": {
      "x": {
        "field": "cell_label",
        "type": "nominal",
        "title": null,
        "sort": {
          "field": "cell_ord",
          "op": "min"
        },
        "axis": {
          "labelAngle": -40
        }
      },
      "y": {
        "field": "compiler",
        "type": "nominal",
        "title": null,
        "sort": [
          "gcc9",
          "gcc16",
          "clang22"
        ]
      },
      "tooltip": [
        {
          "field": "panel"
        },
        {
          "field": "compiler"
        },
        {
          "field": "grp"
        },
        {
          "field": "flags"
        },
        {
          "field": "median_ms"
        },
        {
          "field": "rel_to_best"
        },
        {
          "field": "cv"
        },
        {
          "field": "n_runs"
        },
        {
          "field": "n_builds"
        },
        {
          "field": "placement"
        }
      ]
    }
  },
  "config": {
    "background": null,
    "font": "ui-monospace, Menlo, Consolas, monospace",
    "axis": {
      "labelFontSize": 10,
      "titleFontSize": 11,
      "grid": false,
      "domainColor": "#8886",
      "tickColor": "#8886"
    },
    "legend": {
      "labelFontSize": 10,
      "titleFontSize": 10
    },
    "header": {
      "labelFontSize": 12,
      "titleFontSize": 11
    },
    "view": {
      "stroke": "transparent"
    }
  }
}
